def normalize_chunks(chunks, shape, typesize):
    """Convenience function to normalize the `chunks` argument for an array
    with the given `shape`."""
    if chunks is None:
        chunks = tuple(int(np.ceil(s / float(ts)))
                       for s, ts in zip(shape, typesize))
    return chunks

