def normalize_compression(compression):
    """Convenience function to normalize the `compression` argument."""
    if compression is None:
        return 'default'
    elif compression == 'auto':
        return 'lzf'
    else:
        return compression


def normalize_order(order):
    """Convenience function to normalize the `order` argument."""
    if order is None:
        return 'C'
    else:
        return order


def normalize_filters(filters):
    """Convenience function to normalize the `filters` argument."""
    if filters is None:
        return []
    elif isinstance(filters, string_types):
        return [filters]
    elif isinstance(filters, list):
        return filters
    else:
        raise ValueError('Filters must be a string, list of strings, or None')


def normalize_fill_value(fill_value, dtype):
    """Convenience function to normalize the `fill_value` argument."""
    if fill_value is None:
        return None
    else:
        return np.asarray(fill_value, dtype=dtype)


